def roadway : Structure := Build.rect 10 .roadway (m (-10)) (m (-10)) (m 400) (m 10)

/-- Yaw rate (deg/s) at instant k of a turn of `rate` beginning at instant 240. -/
def yawAt (rate : Int) (k : Nat) : Q :=
  if 240 ≤ k ∧ k < 300 then Units.degrees rate else Q.zero

/-- Ego at instant k: 10 m/s east, 0.5 m of path per instant. -/
def ego (k : Nat) (rate : Int) (ind : Option TurnIndicatorState) (hand : HandSignal) : RoadUser :=
  let u := Build.user 1 [.motorVehicle] (cm (50 * k), m 0) Build.east (Units.metresPerSecond 10)
    (cm 230, cm 90, cm 75) (some (cm (50 * k)))
  Build.withSignals (Build.withKin u fun kn => { kn with yawRate := some (yawAt rate k) })
    fun s => { s with turnIndicator := ind, handSignal := some hand }

